/*!
 * Themeasy — Lightbox Module
 *
 * Handles initialization and configuration of GLightbox instances.
 *
 * - Single namespace: window.Themeasy.lightbox
 * - Safe to call multiple times (idempotent initialization)
 * - Auto-initializes on DOM ready
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.lightbox = window.Themeasy.lightbox || {}

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  /**
   * Detect the Elementor editor preview.
   *
   * The preview iframe boots the whole frontend bundle, so GLightbox would bind
   * every `.glightbox` anchor and swallow the click the user needs to select and
   * edit the widget. The lightbox is a live-site behavior only.
   *
   * Three signals, because none covers every case on its own: the body class
   * may not be there yet, `isEditMode()` throws if the frontend has not read its
   * config yet, and the config global is printed inline before any script runs.
   *
   * @return {boolean}
   */
  function isElementorEditor() {
    if (document.body && document.body.classList.contains('tms-elementor-preview')) return true

    const frontend = window.elementorFrontend

    if (frontend && typeof frontend.isEditMode === 'function') {
      try {
        if (frontend.isEditMode()) return true
      } catch (_) { /* config not ready yet — fall through to the global */ }
    }

    const config = window.elementorFrontendConfig

    return !!(config && config.environmentMode && config.environmentMode.edit)
  }

  // ------------------------------------------------------------------------
  // Lightbox
  // ------------------------------------------------------------------------

  /** @type {GLightbox|null} Active GLightbox instance. */
  let instance = null

  /**
   * Initialize (or reinitialize) the lightbox on all `.glightbox` elements.
   *
   * Safe to call repeatedly — destroys the previous instance before creating
   * a new one so dynamically injected links (Quick View, AJAX) are picked up.
   *
   * No-op inside the Elementor editor preview: an image opening a lightbox on
   * click cannot be selected or edited on the canvas.
   */
  window.Themeasy.lightbox.init = function () {
    if (isElementorEditor()) return
    if (typeof window.GLightbox !== 'function') return

    // Destroy previous instance to pick up new DOM elements.
    if (instance) {
      try { instance.destroy() } catch (_) { /* noop */ }
      instance = null
    }

    const links = document.querySelectorAll('.glightbox')
    if (!links.length) return

    const options = {
      selector: '.glightbox',
      touchNavigation: true,
      loop: true,
      autoplayVideos: true,
      openEffect: 'fade',
      closeEffect: 'fade',
    }

    // Only when the data arrived: GLightbox deep-merges its options, so an
    // undefined `plyr` key would wipe its defaults and break every video slide.
    const plyr = getPlyrOptions()
    if (plyr) options.plyr = plyr

    instance = GLightbox(options)
  }

  /**
   * Point GLightbox's video player (Plyr) at the plugin's own copy.
   *
   * GLightbox defaults to cdn.plyr.io for plyr.js / plyr.css, and Plyr has two
   * defaults there too: its icon sprite and the "blank video" it swaps in to
   * cancel a download. The URLs come from PHP (`themeasyLightbox`, localized on
   * this handle), and the blank video is left empty: an empty `src` aborts the
   * load with no request. `config` merges into GLightbox's default Plyr config,
   * so ratio and provider settings survive.
   *
   * @return {Object|null}
   */
  function getPlyrOptions() {
    const data = window.themeasyLightbox && window.themeasyLightbox.plyr

    if (!data || !data.js || !data.css) return null

    const options = { css: data.css, js: data.js, config: { blankVideo: '' } }
    if (data.iconUrl) options.config.iconUrl = data.iconUrl

    return options
  }

  /**
   * Return the current GLightbox instance (for advanced integrations).
   *
   * @return {GLightbox|null}
   */
  window.Themeasy.lightbox.getInstance = function () {
    return instance
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector('.glightbox')) {
      window.Themeasy.lightbox.init()
    }
  }

  window.Themeasy.lightbox.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(function () {
    window.Themeasy.lightbox.boot()
  })

})(window, document)
